import assert from 'node:assert/strict';
import fs from 'node:fs';
import crypto from 'node:crypto';
import {pathToFileURL} from 'node:url';
import {gunzipSync} from 'node:zlib';
const engineURL=process.env.ENGINE_FILE?pathToFileURL(process.env.ENGINE_FILE):new URL('../prototypes/dez-clubes-v2/engine.mjs',import.meta.url);
const E=await import(engineURL),{createGame,choose,validGame,overall,CLUBS,POSITIONS}=E;
const clone=x=>JSON.parse(JSON.stringify(x)),pick=(g,key)=>g.event.choices.find(c=>c.id.split('@')[0]===key);
const groups=[],metrics={};
const check=(name,fn)=>{try{fn();groups.push({name,pass:true});console.log('PASS',name);}catch(e){groups.push({name,pass:false,error:e.message});console.error('FAIL',name,e.message);}};
const mean=xs=>xs.reduce((s,x)=>s+x,0)/xs.length;
function policy(g,{style=0,entry=0,move=false,recovery='READ',formation=null,rival='earn',decisive='safe'}={}){const k=g.event.kind;if(k==='FORMATION')return g.event.choices[formation??g.formation];if(k==='ENTRY')return g.event.choices[entry];if(k==='RIVALRY')return pick(g,'rival:'+rival);if(k==='ROUTINE')return pick(g,'routine:TRAIN');if(k==='PLAN')return g.event.choices[style];if(k==='RECOVERY')return pick(g,'recovery:'+recovery);if(k==='DECISIVE')return pick(g,'decisive:'+decisive);if(move&&['INTEREST','CONTACT','OFFER'].includes(k))return g.event.choices[0];return pick(g,'market:stay')??g.event.choices[0];}
function youth(position,seed,formation=null){const g=createGame('Agency pública',position,seed);while(g.event.kind==='FORMATION')assert(choose(g,policy(g,{formation}).id));assert(validGame(g));return g;}
function firstPlan(position,seed,options={}){const g=youth(position,seed,options.formation??null);let guard=0;while(g.event.kind!=='PLAN'){assert(choose(g,policy(g,options).id));assert(++guard<8);}return g;}
function nextPlan(g,options={}){let guard=0;while(g.event.kind!=='PLAN'){assert(choose(g,policy(g,options).id));assert(++guard<12);}return g;}
function sum(ms){return ms.reduce((s,m)=>{if(m.minutes){s.apps++;s.starts+=+m.started;s.minutes+=m.minutes;s.goals+=m.goals;s.assists+=m.assists;s.ratingSum+=m.rating;}return s;},{apps:0,starts:0,minutes:0,goals:0,assists:0,ratingSum:0});}
function menus(g){for(const c of g.event.choices){assert.equal(typeof c.benefit,'string');assert.equal(typeof c.cost,'string');assert(c.benefit.trim()&&c.cost.trim());}}
function finish(g,options={},observer=()=>{},paired=false){let guard=0;while(g.phase!=='DONE'){assert(validGame(g),g.event.kind);observer(g);const c=policy(g,options);assert(c,g.event.kind);const before=JSON.stringify(g),loaded=clone(g);assert.equal(choose(g,'forged@'+g.serial),false);assert.equal(JSON.stringify(g),before);assert(choose(g,c.id),g.event.kind);if(paired){assert(validGame(loaded));assert(choose(loaded,c.id));assert.deepEqual(g,loaded);}const after=JSON.stringify(g);assert.equal(choose(g,c.id),false);assert.equal(JSON.stringify(g),after);assert(++guard<64);}assert(validGame(g));return g;}
check('youth eight positions and four formation policies stay developmental rather than adult-skilled',()=>{const rows=[];for(const {id:position} of POSITIONS)for(let n=1;n<=16;n++)for(const formation of [null,0,1,2]){const g=youth(position,(Math.imul(n,2654435761)+17)>>>0,formation);assert.equal(g.age,18);rows.push({position,formation,ovr:overall(g),maxSkill:Math.max(...Object.values(g.skills))});}metrics.youth={count:rows.length,mean:mean(rows.map(r=>r.ovr)),min:Math.min(...rows.map(r=>r.ovr)),max:Math.max(...rows.map(r=>r.ovr)),maxSkill:Math.max(...rows.map(r=>r.maxSkill)),over60:rows.filter(r=>r.ovr>60).length,byPosition:Object.fromEntries(POSITIONS.map(({id})=>[id,mean(rows.filter(r=>r.position===id).map(r=>r.ovr))]))};assert(metrics.youth.mean>=35&&metrics.youth.mean<=50);assert(metrics.youth.maxSkill<80,'formation reaches adult80skill');assert(metrics.youth.over60/rows.length<.03,'OVR60+ is frequent at18');});
check('formation alternatives have different acquired strengths and no arbitrary genetic change',()=>{for(const position of ['GK','CM','AM','ST']){const a=createGame('Formação pública',position,17),b=clone(a),dna=clone(a.dna);assert(choose(a,pick(a,'formation:technique').id));assert(choose(b,pick(b,'formation:reading').id));assert(Object.keys(a.skills).some(k=>a.skills[k]>b.skills[k]));assert(b.skills.reading>a.skills.reading);assert.deepEqual(a.dna,dna);assert.deepEqual(b.dna,dna);assert.notDeepEqual(a.progression[0].skillChanges,b.progression[0].skillChanges);}});
check('ENTRY offers three viable frozen project profiles salary and actual competition',()=>{assert.equal(typeof E.projectProfile,'function');const rows=[];for(let seed=1;seed<=32;seed++){const g=youth('ST',seed);assert.equal(g.phase,'ENTRY');assert.equal(g.event.kind,'ENTRY');assert.equal(g.clubId,null);assert.equal(g.playedMatches.length,0);assert.equal(g.entryOffers.length,3);assert.equal(new Set(g.entryOffers.map(p=>p.clubId)).size,3);menus(g);const raw=JSON.stringify(g);assert(validGame(clone(g)));assert.equal(JSON.stringify(g),raw);for(const profile of g.entryOffers){const c=pick(g,'entry:'+profile.clubId);assert(c);assert.deepEqual(c.profile,profile);assert.deepEqual(E.projectProfile(g,profile.clubId),profile);assert.equal(JSON.stringify(g),raw,'forecast mutates ENTRY');assert(profile.monthly>0&&profile.starterChance>0&&profile.starterChance<1);assert(profile.trainingQuality>=0&&profile.trainingQuality<=100);assert(profile.minutesEstimate.min>=0&&profile.minutesEstimate.max<=90&&profile.minutesEstimate.min<=profile.minutesEstimate.max);const accepted=clone(g),before=accepted.event.choices[0].id;assert(choose(accepted,pick(accepted,'entry:'+profile.clubId).id));assert.equal(accepted.salary,profile.monthly);assert.equal(accepted.clubProject.clubId,profile.clubId);assert.equal(accepted.clubProject.trainingQuality,profile.trainingQuality);assert.equal(accepted.rival.quality,profile.rivalQuality);assert.equal(accepted.clubProject.origin,'ENTRY');const acceptedRaw=JSON.stringify(accepted);assert.equal(choose(accepted,before),false);assert.equal(JSON.stringify(accepted),acceptedRaw);}rows.push(g.entryOffers.map(p=>({id:p.clubId,chance:p.starterChance,pay:p.monthly,training:p.trainingQuality})));}metrics.entry={states:32,branches:96,examples:rows.slice(0,2)};});
check('entry project forecast ranks real minutes against salary and structure in paired periods',()=>{let lowMinutes=0,highMinutes=0,lowPay=0,highPay=0,lowTrain=0,highTrain=0,lowChance=0,highChance=0;for(let seed=1;seed<=64;seed++){const g=youth('ST',seed);assert.equal(g.event.kind,'ENTRY');const profiles=[...g.entryOffers].sort((a,b)=>a.trainingQuality-b.trainingQuality),low=profiles[0],high=profiles.at(-1);assert(high.trainingQuality>low.trainingQuality);assert(high.monthly>low.monthly);assert(high.starterChance<low.starterChance);const results=[];for(const p of [low,high]){const x=clone(g);assert(choose(x,pick(x,'entry:'+p.clubId).id));nextPlan(x);assert(choose(x,pick(x,'intent:ATTACK').id));results.push(x);}lowMinutes+=results[0].lastMatches.reduce((s,m)=>s+m.minutes,0);highMinutes+=results[1].lastMatches.reduce((s,m)=>s+m.minutes,0);lowPay+=low.monthly;highPay+=high.monthly;lowTrain+=low.trainingQuality;highTrain+=high.trainingQuality;lowChance+=low.starterChance;highChance+=high.starterChance;}metrics.projectPairs={pairs:64,low:{minutes:lowMinutes,pay:lowPay/64,training:lowTrain/64,chance:lowChance/64},high:{minutes:highMinutes,pay:highPay/64,training:highTrain/64,chance:highChance/64}};assert(lowMinutes>highMinutes,'advertised minutes tradeoff absent');});
const careers=[];
check('96full careers allpositions signed learning menus contracts replay and exact stats',()=>{let snapshots=0,silent=0,negative=0;for(const {id:position} of POSITIONS)for(let n=1;n<=6;n++)for(let style=0;style<2;style++){const g=createGame('Agency carreira',position,(Math.imul(n,2654435761)+17)>>>0);let initial;finish(g,{entry:style?2:0,style:style?2:0,recovery:style?'EXTRA':'READ',move:n%2===0},x=>{snapshots++;menus(x);if(x.phase==='PRO')initial??=overall(x);if(x.event.kind==='INTEREST')silent+=!x.market.length;},true);assert.equal(g.playedMatches.length,54);assert.equal(g.yearStats.length,3);assert.equal(g.objectiveHistory.length,9);assert.deepEqual(g.totalstats,sum(g.playedMatches));for(const y of g.yearStats)assert.deepEqual(Object.fromEntries(Object.keys(g.totalstats).map(k=>[k,y[k]])),sum(g.playedMatches.filter(m=>m.season===y.season)));for(const m of g.playedMatches)assert(m.goals+m.assists<=m.gf&&m.gf<=m.teamChances&&m.ga<=m.oppChances&&m.assists<=m.keyPasses&&m.keyPasses<=m.completedPasses&&m.completedPasses<=m.passAttempts);assert(g.salary>0);assert(Array.isArray(g.marketHistory));assert(validGame(clone(g)));negative+=g.progression.filter(p=>p.period>0&&Object.values(p.skillChanges).some(d=>d<0)).length;const replay=createGame(g.name,g.position,g.seed);for(const c of g.choicesLog)assert(choose(replay,c.id));assert.deepEqual(replay,g);careers.push({g,initial});}metrics.careers={count:careers.length,fixtures:careers.length*54,snapshots,silentWindows:silent,negativePeriods:negative,initial:mean(careers.map(x=>x.initial)),final:mean(careers.map(x=>overall(x.g))),starts:mean(careers.map(x=>x.g.totalstats.starts)),goals:mean(careers.map(x=>x.g.totalstats.goals)),pressure:mean(careers.map(x=>x.g.pressure))};});
check('finishing20vs80 increases accuracy and conversion conditional on real shots',()=>{const sums={low:{shots:0,target:0,goals:0},high:{shots:0,target:0,goals:0}};for(let seed=1;seed<=64;seed++){const base=firstPlan('ST',seed);for(const [label,finishing]of [['low',20],['high',80]]){const g=clone(base);for(const k of Object.keys(g.skills))g.skills[k]=95;g.skills.finishing=finishing;g.proficiency=95;g.trust=100;g.confidence=80;assert(validGame(g));assert(choose(g,pick(g,'intent:ATTACK').id));for(const m of g.lastMatches){sums[label].shots+=m.shots;sums[label].target+=m.shotsOnTarget;sums[label].goals+=m.goals;}}}for(const value of Object.values(sums)){assert(value.shots>0&&value.target>0);value.accuracy=value.target/value.shots;value.conversion=value.goals/value.target;}metrics.finishing=sums;assert(sums.high.accuracy>sums.low.accuracy);assert(sums.high.conversion>sums.low.conversion);});
check('CM attack produces more real shots and load with less defensive cover than control',()=>{const totals={ATTACK:{shots:0,goals:0,passes:0,opp:0,condition:0,fatigue:0},CONTROL:{shots:0,goals:0,passes:0,opp:0,condition:0,fatigue:0}};for(let seed=1;seed<=64;seed++){const base=firstPlan('CM',seed);for(const intent of ['ATTACK','CONTROL']){const g=clone(base);assert(choose(g,pick(g,'intent:'+intent).id));for(const m of g.lastMatches){totals[intent].shots+=m.shots;totals[intent].goals+=m.goals;totals[intent].passes+=m.completedPasses;totals[intent].opp+=m.oppChances;}totals[intent].condition+=g.condition;totals[intent].fatigue+=g.fatigue;}}metrics.cmTactics=totals;assert(totals.ATTACK.shots>totals.CONTROL.shots);assert(totals.ATTACK.condition<totals.CONTROL.condition);assert(totals.ATTACK.fatigue>totals.CONTROL.fatigue);assert(totals.ATTACK.opp>totals.CONTROL.opp);assert(totals.CONTROL.passes>totals.ATTACK.passes);});
check('rival cooperation reduces own shots while challenge incurs pressure and target costs',()=>{const sums={earn:{shots:0,passes:0,pressure:0},team:{shots:0,passes:0},challenge:{pressure:0}};for(let seed=1;seed<=48;seed++){const g=youth('ST',seed);if(g.event.kind==='ENTRY')assert(choose(g,g.event.choices[0].id));assert.equal(g.event.kind,'RIVALRY');const earned=clone(g),challenged=clone(g);assert(choose(earned,pick(earned,'rival:earn').id));assert(choose(challenged,pick(challenged,'rival:challenge').id));for(const x of [earned,challenged])nextPlan(x);assert(challenged.objective.target.good>earned.objective.target.good);for(const x of [earned,challenged]){assert(choose(x,pick(x,'intent:ATTACK').id));}sums.earn.pressure+=earned.pressure;sums.challenge.pressure+=challenged.pressure;for(const rival of ['earn','team']){const x=clone(g);assert(choose(x,pick(x,'rival:'+rival).id));nextPlan(x);assert(choose(x,pick(x,'intent:ATTACK').id));for(const m of x.lastMatches){sums[rival].shots+=m.shots;sums[rival].passes+=m.completedPasses;}}}metrics.rival=sums;assert(sums.challenge.pressure>sums.earn.pressure,'challenge aggregate pressure cost missing after real periods');assert(sums.team.shots<sums.earn.shots);assert(sums.team.passes>sums.earn.passes);});
check('recovery changes learned skill and effort rather than granting immediate place',()=>{let used=0;const sums={EXTRA:{finish:0,reading:0,condition:0,fatigue:0},READ:{finish:0,reading:0,condition:0,fatigue:0}};for(let seed=1;seed<=64&&used<16;seed++){const g=firstPlan('ST',seed);let guard=0;while(g.phase!=='DONE'&&g.event.kind!=='RECOVERY'){assert(choose(g,policy(g).id));assert(++guard<50);}if(g.event.kind!=='RECOVERY')continue;for(const work of ['EXTRA','READ']){const x=clone(g),trust=x.trust,past=clone(x.playedMatches);assert(choose(x,pick(x,'recovery:'+work).id));assert.equal(x.trust,trust);assert.deepEqual(x.playedMatches,past);nextPlan(x);const skills=clone(x.skills);assert(choose(x,pick(x,'intent:ATTACK').id));sums[work].finish+=x.skills.finishing-skills.finishing;sums[work].reading+=x.skills.reading-skills.reading;sums[work].condition+=x.condition;sums[work].fatigue+=x.fatigue;}used++;}assert.equal(used,16);metrics.recovery={pairs:used,...sums};assert(sums.EXTRA.finish>sums.READ.finish);assert(sums.READ.reading>sums.EXTRA.reading);assert(sums.EXTRA.condition<sums.READ.condition);});
check('natural demanding or inactive projects can lose skills and signed deltas stay valid',()=>{assert.equal(careers.length,96);const primary={GK:'goalkeeping',CB:'defending',FB:'defending',DM:'defending',CM:'passing',AM:'passing',WG:'finishing',ST:'finishing'};const relevantLosses=careers.flatMap(({g})=>g.progression.filter(p=>p.period>0&&p.skillChanges[primary[g.position]]<0).map(p=>({position:g.position,season:p.season,period:p.period,delta:p.skillChanges[primary[g.position]]})));metrics.naturalRelevantLosses=relevantLosses;// The06 cohort has less senior opportunity; keep its zero count visible and exercise documented natural overload paths separately.
const overloadLosses=[];if(!relevantLosses.length)for(const [position,seed]of [['GK',2027808469],['CB',3428989612]]){const g=createGame('Sobrecarga pública',position,seed);finish(g,{formation:0,entry:0,style:2,recovery:'EXTRA',decisive:'risk'});for(const p of g.progression)if(p.period>0&&p.skillChanges[primary[position]]<0)overloadLosses.push({position,seed,season:p.season,period:p.period,delta:p.skillChanges[primary[position]]});}metrics.naturalOverloadRelevantLosses=overloadLosses;assert(relevantLosses.length||overloadLosses.length,'only unused skills lost; natural relevant ability never declines');assert(metrics.careers.negativePeriods>0,'alladultskillsalwaysincrease');for(const {g}of careers){assert(validGame(g));for(const p of g.progression)for(const d of Object.values(p.skillChanges))assert(Number.isFinite(d));}});
check('unused finishing for GK and goalkeeping for CM do not gain automatically in adulthood',()=>{const rows=[];for(const [position,key]of [['GK','finishing'],['CM','goalkeeping']])for(let seed=1;seed<=12;seed++){const g=firstPlan(position,seed),before=g.skills[key];finish(g);const delta=g.skills[key]-before;rows.push({position,seed,delta});assert(delta<=.03,'unused '+position+'/'+key+' increased '+delta);}metrics.unused={cases:rows.length,mean:mean(rows.map(r=>r.delta))};});
check('market frozen profiles apply salary competition and structure while staying preserves contract',()=>{assert.equal(typeof E.projectProfile,'function');const template=firstPlan('ST',7);for(const k of Object.keys(template.skills))template.skills[k]=60;template.proficiency=95;template.trust=85;assert(validGame(template));while(!(template.event.kind==='PLAN'&&template.period===2))assert(choose(template,policy(template).id));let pair=null;for(let n=1;n<=512&&!pair;n++){const g=clone(template);g.rng=(Math.imul(n,2654435761)+17)>>>0;assert(choose(g,pick(g,'intent:ATTACK').id));if(g.event.kind!=='INTEREST')continue;const aid=g.market.find(id=>CLUBS.find(c=>c.id===id).division==='A'),bid=g.market.find(id=>CLUBS.find(c=>c.id===id).division==='B');if(!aid||!bid)continue;for(let rng=0;rng<32&&!pair;rng++){const offers=[];for(const id of [bid,aid]){const x=clone(g);assert(choose(x,pick(x,'contact:'+id).id));x.rng=rng;assert(validGame(x));assert(choose(x,pick(x,'offer:'+id).id));if(x.event.kind!=='OFFER')break;offers.push(x);}if(offers.length===2)pair=offers;}}assert(pair,'no A/B pair of actual offered projects found');const [b,a]=pair,low=b.offer.profile,high=a.offer.profile;assert(low&&high);assert(high.monthly>low.monthly);assert(high.trainingQuality>low.trainingQuality);assert(high.starterChance<low.starterChance);assert(high.pressure>low.pressure);const stay=clone(a),oldProject=clone(stay.clubProject),oldSalary=stay.salary,oldClub=stay.clubId;assert(choose(stay,pick(stay,'market:stay').id));assert.equal(stay.clubId,oldClub);assert.equal(stay.salary,oldSalary);assert.deepEqual(stay.clubProject,oldProject);for(const g of pair){const p=clone(g.offer.profile);assert(choose(g,pick(g,'accept:'+p.clubId).id));assert.equal(g.salary,p.monthly);assert.equal(g.clubProject.trainingQuality,p.trainingQuality);assert.equal(g.rival.quality,p.rivalQuality);assert.equal(g.clubProject.origin,'MARKET');assert(validGame(g));}metrics.marketProfiles={B:low,A:high,staySalary:oldSalary};});
// LEGACY04_PACK is synthetic/public: eight event snapshots generated from a39a8ce, ST public seed1.
const LEGACY04_PACK='';
check('02 and04 frozen snapshots preserve every factual prefix and continue to DONE',()=>{const old02=JSON.parse(fs.readFileSync(new URL('./fixtures/dez-clubes-v2-legacy-head.json',import.meta.url))).snapshots,old04=JSON.parse(gunzipSync(Buffer.from(LEGACY04_PACK,'base64'))).snapshots,rows=[];for(const [version,bank]of [['02',old02],['04',old04]])for(const [kind,snapshot]of Object.entries(bank)){const g=clone(snapshot),before=clone(g),raw=JSON.stringify(g);assert(validGame(g),version+kind);assert.equal(JSON.stringify(g),raw);if(version==='04'&&kind==='PLAN'){const pending=clone(g.objective);assert.equal(g.mechanicsRevision,undefined);assert(choose(g,policy(g).id));const resolved=g.objectiveHistory.at(-1);for(const key of ['target','metric','intent','revision','season','period','clubId'])assert.deepEqual(resolved[key],pending[key],'04 pending goal changed '+key);assert(g.lastMatches.every(m=>m.mechanicsRevision===undefined));}if(kind==='DONE'){assert.equal(choose(g,'forged@'+g.serial),false);assert.equal(JSON.stringify(g),raw);}else finish(g,{move:true},()=>{},true);for(const key of ['playedMatches','objectiveHistory','progression','choicesLog','history','yearStats'])assert.deepEqual(g[key].slice(0,before[key].length),before[key],version+kind+' changed '+key);rows.push({version,kind,preservedMatches:before.playedMatches.length,finishedMatches:g.playedMatches.length});}metrics.legacy=rows;});
check('ENTRY and frozen offers malformed fields reject before mutation',()=>{const base=youth('ST',9);assert.equal(base.event.kind,'ENTRY');const mutations=[g=>g.entryOffers=null,g=>g.entryOffers[0]=null,g=>g.entryOffers[0].clubId='unknown',g=>g.entryOffers[0].monthly=-1,g=>g.entryOffers[0].monthly='wrong',g=>g.entryOffers[0].trainingQuality=101,g=>g.entryOffers[0].starterChance=2,g=>g.entryOffers[0].rivalQuality=NaN,g=>g.entryOffers[0].benefit='',g=>g.entryOffers[0].cost=null,g=>g.entryOffers[0].minutesEstimate.min=91,g=>g.event.choices[0].profile.clubId='unknown',g=>g.entryOffers[1]=clone(g.entryOffers[0]),g=>delete g.seed,g=>g.mechanicsRevision=999];for(const mutate of mutations){const g=clone(base);mutate(g);const before=JSON.stringify(g);assert.equal(validGame(g),false);assert.doesNotThrow(()=>assert.equal(choose(g,g.event.choices[0].id),false));assert.equal(JSON.stringify(g),before);}metrics.malformedEntry=mutations.length;});
const report={engineSha256:crypto.createHash('sha256').update(fs.readFileSync(engineURL)).digest('hex'),groups,metrics};if(process.env.REPORT_FILE)fs.writeFileSync(process.env.REPORT_FILE,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({groups:groups.length,passed:groups.filter(g=>g.pass).length,metrics},null,2));if(groups.some(g=>!g.pass))process.exitCode=1;
